const DICT: Record<Lang, Record<Key, string>> = { en, ta, hi }
export type T = (key: Key, vars?: Record<string, string | number | null | undefined>) => string
/** Translate a key built at run time (for example `cause.${code}`); returns `fallback` when there is no such key. */
export type TMaybe = (key: string, fallback: string, vars?: Record<string, string | number | null | undefined>) => string

const fill = (s: string, vars?: Record<string, string | number | null | undefined>) =>
  vars ? s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] == null ? m : String(vars[k]))) : s

interface Ctx { lang: Lang; setLang: (l: Lang) => void; t: T; tm: TMaybe; speech: string; ago: (ts: number) => string }
const I18n = createContext<Ctx>(null as never)

function initial(): Lang {
  const q = new URLSearchParams(location.search).get('lang')            // ?lang=ta|hi|en opens the app in that language
  if (q && q in DICT) return q as Lang
  try {
    const s = localStorage.getItem('lang')
    if (s && s in DICT) return s as Lang
  } catch { /* storage blocked */ }
  const nav = navigator.language.slice(0, 2)
  return nav in DICT ? (nav as Lang) : 'en'
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initial)
  const setLang = useCallback((l: Lang) => {
    setLangState(l)
    try { localStorage.setItem('lang', l) } catch { /* storage blocked */ }
  }, [])
  // The agents write in the dashboard's language, so the backend is told whenever it changes
  useEffect(() => {
    document.documentElement.lang = lang
    api('/settings', { body: { language: lang } }).catch(() => { /* backend not up yet; sent again on next change */ })
  }, [lang])
  const value = useMemo<Ctx>(() => {
    const d = DICT[lang]
    const t: T = (key, vars) => fill(d[key] ?? en[key] ?? key, vars)
    const tm: TMaybe = (key, fallback, vars) => (key in d ? fill(d[key as Key], vars) : fallback)
    const ago = (ts: number) => {
      const s = Math.max(0, Date.now() / 1000 - ts)
      return s < 60 ? t('c.agoS', { n: Math.round(s) }) : s < 3600 ? t('c.agoMin', { n: Math.round(s / 60) }) : t('c.agoH', { n: (s / 3600).toFixed(1) })
    }
    return { lang, setLang, t, tm, speech: LANGS.find((l) => l.code === lang)!.speech, ago }
  }, [lang, setLang])
  return <I18n.Provider value={value}>{children}</I18n.Provider>
}

export const useI18n = () => useContext(I18n)
